local str1 = "Library"
local var1 = require(game:GetService("ReplicatedStorage"):WaitForChild("Framework"):WaitForChild(str1))
local tbl1 = {}
for k1, v1 in script:GetChildren() do
	tbl1[v1.Name] = require(v1)
end

for k2, v2 in tbl1, nil do
	v2.Id = k2
	for k3, v3 in v2.Stats, nil do
		v3.Id = k3
		local bool1 = false
		if v3.Reward ~= nil then
			bool1 = v3.Efficiency ~= false
		end

		v3.Efficiency = bool1
		bool1 = v3.Efficiency and ("%*%*Efficiency"):format(k2, k3) or ("%*%*"):format(k2, k3)
		v3.Boost = bool1
	end

	for k4, v4 in v2.Parts, nil do
		v4.Id = k4
	end

	for k5, v5 in v2.Vehicles, nil do
		v5.Id = k5
	end

	local var2 = v2.SkipCost
	for k6, v6 in v2.Routes, nil do
		v6.Id = k6
		if not var2 then
			continue
		end

		local var3 = math.max(math.round(var2.Base * (v6.Time / var2.Time) ^ var2.Exponent / var2.Round), 1) * var2.Round
		v6.SkipPrices = {}
		for i1 = 1, var2.Steps do
			v6.SkipPrices[i1] = math.round(var3 * i1 / var2.Steps)
		end
	end

	for k7, v7 in v2.Groups, nil do
		v7.Id = k7
	end

	for k8, v8 in v2.Docks, nil do
		v8.Id = ("%*"):format(k8)
		v8.Order = k8
	end
end

for k9, v9 in var1.Collection:GetTagged("Expedition") do
	local var5 = tbl1[v9:GetAttribute("Id")]
	if not var5 then
		warn(v9:GetFullName(), "Expedition Id Not Found!")
	else
		v9.Name = "Expedition"
		v9:SetAttribute("Color", var5.Color.Keypoints[1].Value)
		local var6 = var5.InteractIcon
		v9:SetAttribute("Icon", var6 or var5.Icon)
		v9:SetAttribute("Model", "Explosion")
		v9:SetAttribute("Name", var5.Name)
		v9:SetAttribute("Size", 1)
		v9:SetAttribute("OffsetY", 3)
	end
end

return tbl1

