--- ReplicatedStorage.Framework.Modules.Data.CrewmateData [ModuleScript]
-- y u r i

local str1 = "Library"
local var1 = require(game:GetService("ReplicatedStorage"):WaitForChild("Framework"):WaitForChild(str1))
local tbl1 = {}
for k1, v1 in var1:GetData("ExpeditionData") do
	if v1.UnitSystem ~= "Crewmate" then
		continue
	end

	for k2, v2 in v1.Groups, nil do
		local var2 = v1.Stats[v2.Stat].Boost
		for k3, v3 in v2.Members, nil do
			local var3 = v3.Id
			local var4 = v3.Name
			var3 = var3 or var4:gsub("%W", "")
			local var5 = v1.Rarities[k3]
			local tbl2 = { Name = var4, Rarity = var5, Chance = var1.Utils:GetBannerChances("Crewmate")[var5] }
			tbl2.Type = k2
			tbl2.Group = k2
			tbl2.GroupName = v2.Name
			tbl2.Expedition = k1
			tbl2.Icon = v3.Icon or "rbxassetid://104427713016481"
			tbl2.Desc = ("A member of the %*."):format(v2.Name)
			tbl2.Boost = { [var2] = v1.Values[var5] }
			tbl1[var3] = tbl2
		end
	end
end

return tbl1

