	describe("Promise:cancel", function()
		it("should mark promises as cancelled and not resolve or reject them", function()
			local num1 = 0
			local num2 = 0
			local var2 = var1.new(function()
			end):andThen(function()
				local var1 = num1 + 1
				num1 = var1
			end):finally(function()
				local var1 = num2 + 1
				num2 = var1
			end)

			var2:cancel()
			var2:cancel()
			expect(num1).to.equal(0)
			expect(num2).to.equal(1)
			expect(var2:getStatus()).to.equal(var1.Status.Cancelled)
		end)

		it("should call the cancellation hook once", function()
			local num1 = 0
			local var2 = var1.new(function(_, _, arg3)
				arg3(function()
					local var1 = num1 + 1
					num1 = var1
				end)
			end)

			var2:cancel()
			var2:cancel()
			expect(num1).to.equal(1)
		end)

		it("should propagate cancellations", function()
			local var2 = var1.new(function()
			end)

			expect(var2:getStatus()).to.equal(var1.Status.Started)
			local var3 = var2:andThen()
			expect(var3:getStatus()).to.equal(var1.Status.Started)
			local var4 = var2:andThen()
			expect(var4:getStatus()).to.equal(var1.Status.Started)
			var3:cancel()
			expect(var2:getStatus()).to.equal(var1.Status.Started)
			expect(var3:getStatus()).to.equal(var1.Status.Cancelled)
			expect(var4:getStatus()).to.equal(var1.Status.Started)
			var4:cancel()
			expect(var2:getStatus()).to.equal(var1.Status.Cancelled)
			expect(var3:getStatus()).to.equal(var1.Status.Cancelled)
			expect(var4:getStatus()).to.equal(var1.Status.Cancelled)
		end)

		it("should affect downstream promises", function()
			local var2 = var1.new(function()
			end)

			var2:cancel()
			expect(var2:andThen():getStatus()).to.equal(var1.Status.Cancelled)
		end)

		it("should track consumers", function()
			local var2 = var1.new(function()
			end)

			local var3 = var1.resolve()
			local var4 = var3:andThen(function()
				return var2
			end)

			local var5 = var1.new(function(arg1)
				arg1(var4)
			end)

			expect(var4._parent).to.never.equal(var3)
			expect(var5._parent).to.never.equal(var4)
			local var6 = var5:andThen(function()
			end)

			expect(var5._consumers[var6]).to.be.ok()
			expect(var6._parent).to.equal(var5)
		end)

		it("should cancel resolved pending promises", function()
			local var2 = var1.new(function()
			end)

			local var3 = var1.new(function(arg1)
				arg1(var2)
			end):finally(function()
			end)

			var3:cancel()
			expect(var2._status).to.equal(var1.Status.Cancelled)
			expect(var3._status).to.equal(var1.Status.Cancelled)
		end)

		it("should close the promise thread", function()
			local num1 = 0
			var1.new(function()
				local var2 = num1 + 1
				num1 = var2
				var1.delay(1):await()
				var2 = num1 + 1
				num1 = var2
