			end)

			var2:finally(function()
				bool1 = true
			end)

			var2:andThen(function()
			end):cancel()

			expect(var2:getStatus()).to.equal(var1.Status.Cancelled)
			expect(bool1).to.equal(true)
		end)

		it("should propagate cancellation downwards", function()
			local bool1 = false
			local var2 = var1.new(function()
			end)

			var2:cancel()
			expect(var2:getStatus()).to.equal(var1.Status.Cancelled)
			expect(var2:finally(function()
				bool1 = true
			end):getStatus()).to.equal(var1.Status.Cancelled)

			expect(bool1).to.equal(true)
			expect(false).to.equal(false)
		end)

		it("should propagate cancellation upwards", function()
			local bool1 = false
			local var2 = var1.new(function()
			end)

			local var3 = var2:finally(function()
				bool1 = true
			end)

			var3:cancel()
			expect(var2:getStatus()).to.equal(var1.Status.Cancelled)
			expect(var3:getStatus()).to.equal(var1.Status.Cancelled)
			expect(bool1).to.equal(true)
			expect(false).to.equal(false)
